<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import {useUserStore} from '@/stores/user'
import {newRequestId} from '@/api/modules/partner'
import {sampleShipmentAction} from '@/api/modules/sampleManagement'
import type {SampleShipment} from '@/types/sampleManagement'
const props=defineProps<{shipment:SampleShipment;action:'dispatched'|'tracking'|'receive'|'loss';refs?:unknown[]}>(),emit=defineEmits<{close:[];saved:[value:SampleShipment]}>()
const user=useUserStore(),auth=user.token,busy=ref(false),error=ref(''),dirty=ref(false),disposed=ref(false),unknown=ref(false)
const form=reactive({date:'',tracking:props.shipment.dispatch?.tracking||'',carrier:props.shipment.dispatch?.carrier||'',location:'',person:'',note:'',reason:'',requestId:newRequestId(),rows:props.shipment.rows.map(row=>({rowId:row.rowId,qty:props.action==='dispatched'?(row.qty??undefined):undefined as number|undefined,goodQty:0,damagedQty:0}))})
const actor=String(user.profile?.userId||''),pendingKey=actor?`plm:sample-shipment:${actor}:${props.shipment.id}:${props.action}`:''
let pendingPayload:Record<string,unknown>|undefined
const clearPending=()=>{pendingPayload=undefined;if(pendingKey)try{sessionStorage.removeItem(pendingKey)}catch{}}
try{const stored=pendingKey?sessionStorage.getItem(pendingKey):null;if(stored){const saved=JSON.parse(stored) as {requestId?:unknown;date?:unknown;tracking?:unknown;carrier?:unknown;location?:unknown;person?:unknown;note?:unknown;reason?:unknown;rows?:{rowId:string;qty?:number;goodQty?:number;damagedQty?:number}[]};if(typeof saved.requestId==='string'&&(Array.isArray(saved.rows)||props.action==='tracking')){pendingPayload=saved as Record<string,unknown>;Object.assign(form,{requestId:saved.requestId,date:String(saved.date||''),tracking:String(saved.tracking||''),carrier:String(saved.carrier||''),location:String(saved.location||''),person:String(saved.person||''),note:String(saved.note||''),reason:String(saved.reason||'')});for(const row of form.rows){const old=saved.rows?.find(value=>value.rowId===row.rowId);if(old)Object.assign(row,{qty:old.qty??row.qty,goodQty:old.goodQty??0,damagedQty:old.damagedQty??0})}unknown.value=true;error.value='上次实际记录的保存结果待核对，请先核对，避免重复办理。'}}}catch{clearPending()}
const title=computed(()=>({dispatched:'登记本次实际寄出',tracking:'记录物流节点',receive:'登记本次实际签收',loss:'确认在途短少／丢失'}[props.action]))
const source=(id:string)=>props.shipment.rows.find(row=>row.rowId===id)
watch(form,()=>{dirty.value=true},{deep:true})
watch(()=>user.token,()=>{disposed.value=true;emit('close')})
async function close(){if(busy.value)return;if(unknown.value){error.value='请先核对本次保存结果，避免重复记录实际数量';return}if(dirty.value)try{await ElMessageBox.confirm('放弃本次尚未保存的实际记录？','保留填写',{confirmButtonText:'放弃',cancelButtonText:'继续填写'})}catch{return}emit('close')}
async function save(){error.value='';if(!form.date){error.value='请填写本次实际日期';return}if(props.action==='receive'&&!form.location.trim()){error.value='请填写实际收到后的简单存放位置';return}if(props.action==='dispatched'&&!form.tracking.trim()){error.value='请填写运单／物流依据';return}if(props.action==='tracking'&&!form.note.trim()){error.value='请填写本次人工物流节点';return}if(props.action==='loss'&&!form.reason.trim()){error.value='请填写核实原因';return}if(props.action==='receive'&&!form.rows.some(row=>row.goodQty>0||row.damagedQty>0)){error.value='请逐项填写本次实际收到数量';return}if(['dispatched','loss'].includes(props.action)&&!form.rows.some(row=>Number(row.qty)>0)){error.value='请填写本次实际数量';return}busy.value=true;try{const base={version:props.shipment.version,requestId:form.requestId,date:form.date,refs:props.refs||[],note:form.note};const data=props.action==='receive'?{...base,location:form.location.trim(),person:form.person.trim(),rows:form.rows.filter(row=>row.goodQty>0||row.damagedQty>0).map(({rowId,goodQty,damagedQty})=>({rowId,goodQty,damagedQty}))}:props.action==='loss'?{...base,reason:form.reason.trim(),rows:form.rows.filter(row=>Number(row.qty)>0).map(({rowId,qty})=>({rowId,qty}))}:props.action==='dispatched'?{...base,tracking:form.tracking.trim(),carrier:form.carrier.trim(),rows:form.rows.map(({rowId,qty})=>{const original=source(rowId)!;return {rowId,qty,sampleIdentityId:original.sampleIdentityId,batchId:original.batchId,location:original.location,selectionRowId:original.selectionRowId,phoneModelId:original.phoneModelId,colorId:original.colorId,name:original.name,specName:original.specName}})}:{...base,tracking:form.tracking.trim(),carrier:form.carrier.trim()};const payload=pendingPayload||data;pendingPayload=payload;if(pendingKey)try{sessionStorage.setItem(pendingKey,JSON.stringify(payload))}catch{}const next=await sampleShipmentAction(props.shipment.id,props.action,payload);if(!disposed.value&&auth===user.token){clearPending();unknown.value=false;dirty.value=false;emit('saved',next)}}catch(e){if(auth===user.token){const failure=e as {code?:string;response?:{status?:number}};unknown.value=!!pendingPayload&&(['ERR_NETWORK','ECONNABORTED','ETIMEDOUT'].includes(failure.code||'')||Number(failure.response?.status)>=500);if(unknown.value)error.value='保存结果待核对，请核对本次保存结果，不会另记一笔实际数量';else{clearPending();error.value=e instanceof Error?e.message:'保存失败，请保留填写并重试'}}}finally{busy.value=false}}
onBeforeUnmount(()=>{disposed.value=true})
</script>
<template><el-dialog class="sample-shipment-action-dialog" :model-value="true" :title="title" width="min(800px,96vw)" append-to-body :close-on-click-modal="false" :before-close="close"><div class="shipment-action"><p>{{shipment.code}} · {{shipment.name}} · {{shipment.origin||'寄出地点待补'}} → {{shipment.destination||'收货地点待补'}}</p><el-form label-position="top" :disabled="busy||unknown"><el-form-item label="本次实际日期 *"><el-date-picker v-model="form.date" type="date" value-format="YYYY-MM-DD"/></el-form-item><template v-if="action==='dispatched'||action==='tracking'"><el-form-item label="运单／物流依据"><el-input v-model="form.tracking"/></el-form-item><el-form-item label="承运方（选填）"><el-input v-model="form.carrier"/></el-form-item></template><template v-if="action==='receive'"><el-form-item label="收到后的存放位置 *"><el-input v-model="form.location" placeholder="填写实际地点即可"/></el-form-item><el-form-item label="实际接收人"><el-input v-model="form.person"/></el-form-item></template><div v-if="action!=='tracking'" class="action-rows"><article v-for="row in form.rows" :key="row.rowId"><strong>{{source(row.rowId)?.sampleCode||source(row.rowId)?.name||'本次样品'}} · {{source(row.rowId)?.specName}}</strong><template v-if="action==='receive'"><label>本次完好实收<el-input-number v-model="row.goodQty" :min="0" :precision="0" size="small"/></label><label>本次损坏实收<el-input-number v-model="row.damagedQty" :min="0" :precision="0" size="small"/></label></template><label v-else>{{action==='loss'?'本次核实短少／丢失':'本次实际寄出数量'}}<el-input-number v-model="row.qty" :min="action==='loss'?0:1" :precision="0" :controls="false" size="small"/></label></article></div><el-form-item v-if="action==='loss'" label="核实原因 *"><el-input v-model="form.reason" type="textarea" autosize/></el-form-item><el-form-item :label="action==='tracking'?'本次人工物流节点 *':'本次说明／差异（选填）'"><el-input v-model="form.note" type="textarea" autosize/></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/></div><template #footer><el-button :disabled="unknown" @click="close">取消</el-button><el-button type="primary" :loading="busy" @click="save">{{unknown?'核对本次保存结果':'保存本次实际记录'}}</el-button></template></el-dialog></template>
<style scoped>.shipment-action{font-size:12px;min-width:0}.shipment-action p{color:#5c7390;overflow-wrap:anywhere}.shipment-action :deep(.el-form-item__label){font-size:12px;font-weight:600;color:#3c5574}.shipment-action :deep(.el-input__wrapper),.shipment-action :deep(.el-date-editor){min-height:28px;font-size:12px;width:100%}.action-rows{border-top:1px solid #dfe8f1}.action-rows article{display:flex;gap:8px 14px;align-items:end;flex-wrap:wrap;padding:10px 0;border-bottom:1px solid #e4ebf3}.action-rows strong{flex-basis:100%;font-size:12px;overflow-wrap:anywhere}.action-rows label{font-size:12px;color:#637b96;display:flex;flex-direction:column;gap:4px}.action-rows :deep(.el-input-number){width:160px}.shipment-action :deep(textarea){font-size:12px}:global(.sample-shipment-action-dialog){display:flex;flex-direction:column;max-height:calc(100dvh - 40px);margin-top:20px;margin-bottom:20px;overflow:hidden}:global(.sample-shipment-action-dialog>.el-dialog__header),:global(.sample-shipment-action-dialog>.el-dialog__footer){flex:none}:global(.sample-shipment-action-dialog>.el-dialog__body){min-height:0;overflow:auto}
</style>
